"""Original reproductive chapter: amenorrhea, ovarian insufficiency and male gonadal disease."""
from create_pcos import rows,q,PC,PO,FH,TE
from qbank_authoring import ref,finalize
KA=ref('GeneReviews: Isolated GnRH Deficiency and Kallmann Syndrome','https://www.ncbi.nlm.nih.gov/sites/books/NBK1334/')
KL=ref('EAA/ESE: Klinefelter Syndrome Guideline','https://doi.org/10.1111/andr.12909')
GY=ref('EAA: Gynecomastia Evaluation and Management Guideline','https://pubmed.ncbi.nlm.nih.gov/31099174/')
q('A reproductive-age patient presents with new secondary amenorrhea. Which diagnosis should generally be excluded first when biologically relevant?', 'Pregnancy',[
 ('PCOS is established from amenorrhea alone','It requires a broader diagnostic assessment.'),('Premature ovarian insufficiency without any testing','Gonadal and central causes need appropriate evaluation.'),('A pituitary tumor is the only explanation','The differential is broad.')],
 'Start with a common consequential and testable cause', '**Pregnancy testing precedes many hormonal or imaging decisions.**',['Contraceptive history does not provide absolute exclusion.','Lactation, medicines, weight change and stress are relevant context.'], '**Then evaluate the axis systematically.**',['TSH, prolactin and gonadotropin/estradiol assessment are selected according to the presentation.','Do not assign a chronic endocrine label before excluding pregnancy.'],[['First branch','Pregnancy when relevant'],['History','Cycle, medicines and energy balance'],['Next tests','Context-directed endocrine evaluation']],[FH,PO],'clinical_scenario')
q('A distance runner develops amenorrhea after restrictive eating and increased training. Estradiol is low with low-normal gonadotropins. Which diagnosis is favored after exclusions?', 'Functional hypothalamic amenorrhea',[
 ('Primary ovarian insufficiency as the typical gonadotropin pattern','POI usually raises FSH.'),('PCOS is proven by every irregular cycle','Energy-deficient central suppression is a different mechanism.'),('Normal fertility is guaranteed because BMI is not very low','Energy availability can be inadequate at a range of BMI values.')],
 'Low energy availability can suppress GnRH pulsatility', '**The diagnosis requires exclusion of pregnancy and organic or endocrine causes.**',['Stress and disordered eating can contribute.','Bone and cardiovascular consequences matter.'], '**Assess medical stability and nutrition.**',['Bradycardia, electrolyte disturbances or severe restriction may require urgent care.','Use a multidisciplinary recovery plan.'],[['Context','Energy deficit/training/stress'],['Hormones','Low estradiol with central pattern'],['Care','Nutrition, psychological and medical assessment']],[FH],'clinical_scenario')
q('What is the central treatment of functional hypothalamic amenorrhea related to low energy availability?', 'Correct the energy imbalance and address exercise and psychological contributors',[
 ('Use a combined pill solely to prove the energy problem is cured','Withdrawal bleeding can mask persistent suppression.'),('Further calorie restriction to stimulate ovulation','This worsens the driver.'),('Ignore bone health until a fracture occurs','Skeletal assessment is part of care.')],
 'Treat the hypothalamic signal’s cause', '**Increased intake, improved nutrition and reduced excessive exercise can restore function.**',['Psychological support is often important.','DXA is generally considered after six months of amenorrhea or earlier with severe risk.'], '**Do not use bleeding alone as the recovery marker.**',['Selected persistent cases can require specialist hormone strategies for bone protection.','Fertility treatment should follow medical and nutritional safety assessment.'],[['Main intervention','Restore adequate energy'],['Support','Psychological/exercise review'],['Monitoring','Cycles, health and bone']],[FH])
q('A 32-year-old has irregular cycles for six months, estrogen-deficiency symptoms and FSH 38 IU/L without confounding hormonal treatment. Which diagnosis is supported by the 2024 guideline?', 'Premature ovarian insufficiency',[
 ('Age below 40 excludes ovarian insufficiency','POI specifically concerns loss of ovarian activity before 40.'),('Two FSH values are mandatory in every unequivocal case','The updated guideline repeats after four to six weeks when uncertainty remains, not as an inflexible requirement for all.'),('Low estrogen with high FSH is a purely hypothalamic pattern','Central suppression generally has low or inappropriate gonadotropins.')],
 'The updated criteria simplify a historically repeated-test definition', '**Disordered cycles for at least four months plus FSH above 25 IU/L support diagnosis.**',['Pregnancy and treatment-related masking must be considered.','Repeat testing is appropriate when the result or context is uncertain.'], '**Assess cause, health effects and reproductive implications.**',['Use sensitive counseling.','Do not equate POI with an absolute impossibility of intermittent ovarian activity.'],[['Age','Under 40'],['Cycles','At least four months disordered'],['FSH','Above 25 IU/L']],[PO],'clinical_scenario')
q('Noniatrogenic POI is diagnosed. Which genetic assessments are recommended in the guideline framework?', 'Chromosomal analysis and FMR1 premutation testing with appropriate counseling',[
 ('No genetic cause is possible without family history','Sporadic presentations occur.'),('Only a PCOS morphology scan is required','That does not investigate ovarian insufficiency etiology.'),('A positive autoimmune antibody excludes every genetic cause without further review','The full etiological context matters.')],
 'A molecular or chromosomal diagnosis affects more than the current symptoms', '**Results can guide family counseling and associated health assessment.**',['FMR1 testing requires the appropriate specific method.','Autoimmune and iatrogenic causes are separate considerations.'], '**Discuss implications before testing.**',['Fertility and family planning need individualized support.','Do not use age alone to deny etiological investigation.'],[['Chromosomes','Assess relevant abnormalities'],['FMR1','Premutation testing'],['Process','Genetic counseling']],[PO])
q('A woman with POI has no contraindication to hormone therapy. What is the general replacement principle?', 'Offer appropriate sex-hormone replacement until the usual age of menopause, with progestogen protection if the uterus is present',[
 ('Apply the same benefit-risk assumptions as starting hormones decades after menopause','Young hormone deficiency has a different context.'),('Estrogen alone is appropriate for every intact uterus','Endometrial protection is usually needed.'),('Hormone therapy guarantees contraception','Intermittent ovarian activity and pregnancy can still occur.')],
 'Physiological replacement in early deficiency differs from late initiation', '**Treatment supports symptoms, bone and broader health.**',['Individual route and dose depend on context.','Contraindications and patient preference still matter.'], '**Discuss contraception separately when needed.**',['Monitor symptoms and health risks.','Provide fertility counseling without presenting replacement as an ovulation-induction therapy.'],[['Goal','Replace early hormone deficiency'],['Intact uterus','Add appropriate progestogen'],['Contraception','Separate consideration']],[PO],'clinical_scenario')
q('A man with reduced libido has one low afternoon testosterone measurement. What is the appropriate diagnostic next step?', 'Confirm symptoms and repeat reliable fasting morning testosterone measurements before diagnosing hypogonadism',[
 ('Start lifelong testosterone from the single afternoon value','Diurnal and biological variation can mislead.'),('Any low result proves permanent testicular failure','Illness, medicines and SHBG effects can alter values.'),('Testosterone measurement is unnecessary if symptoms are nonspecific','Symptoms alone are not sufficient either.')],
 'Diagnosis requires clinical and reproducible biochemical evidence', '**The guideline recommends two separate fasting morning measurements.**',['Acute illness can transiently suppress the axis.','LH and FSH help distinguish primary from central disease once low testosterone is confirmed.'], '**Investigate reversible contributors.**',['Sleep, obesity, opioids and systemic illness matter.','Discuss treatment only after establishing the mechanism and contraindications.'],[['Clinical','Compatible symptoms'],['Biochemistry','Repeated reliable morning values'],['Classification','Gonadotropins and context']],[TE],'clinical_scenario')
q('Total testosterone is borderline low in a man with obesity and low SHBG. Which additional principle is appropriate?', 'Assess free testosterone by a reliable method when indicated rather than interpreting total testosterone alone',[
 ('Low SHBG always means complete androgen deficiency','Binding changes can lower total levels without the same free-hormone reduction.'),('Any direct analog free-testosterone assay is equally reliable','Method quality matters.'),('Symptoms and repeated testing no longer matter once SHBG is low','They remain central to diagnosis.')],
 'Binding proteins affect total hormone concentration', '**Equilibrium dialysis or a validated calculation using reliable inputs can be useful.**',['The appropriate method and reference interval depend on the laboratory.','High SHBG can create the opposite total-versus-free discrepancy.'], '**Integrate the result with symptoms and causes.**',['Do not prescribe to a number in isolation.','Treat reversible metabolic or medication contributors when appropriate.'],[['Low SHBG','Can lower total testosterone'],['Free assessment','Reliable method when indicated'],['Decision','Clinical and repeated biochemical context']],[TE])
q('A man with confirmed central hypogonadism wants fertility soon. Why is exogenous testosterone generally inappropriate as the fertility treatment?', 'It suppresses gonadotropins and can reduce spermatogenesis',[
 ('It reliably stimulates intratesticular testosterone through LH','It suppresses the axis rather than replacing LH action.'),('Testosterone treatment and sperm induction are always identical goals','They require different strategies.'),('Fertility desire has no influence on regimen selection','It is a major determinant.')],
 'Systemic androgen replacement is not a substitute for testicular stimulation', '**Spermatogenesis requires appropriate gonadotropin-driven intratesticular conditions.**',['Gonadotropin or selected GnRH therapy can be used in relevant central disorders.','The cause and partner factors affect the plan.'], '**Use reproductive-endocrine or andrology care.**',['Explain potential recovery and treatment timelines.','Do not start replacement without asking about fertility.'],[['Exogenous testosterone','Suppresses LH/FSH'],['Fertility treatment','Stimulate the axis/testis appropriately'],['Selection','Reproductive goals first']],[TE],'clinical_scenario')
q('Absent puberty, low sex steroids, low gonadotropins and lifelong anosmia occur together. Which diagnosis is suggestive?', 'Kallmann syndrome',[
 ('Primary gonadal failure','Gonadotropins would usually be elevated.'),('An ordinary isolated thyroid nodule','It does not explain the GnRH and olfactory phenotype.'),('PCOS as the unifying mechanism in all sexes','This is a congenital central reproductive disorder.')],
 'Reproductive and olfactory development can share a defect', '**Kallmann syndrome is congenital GnRH deficiency with impaired smell.**',['Normosmic GnRH deficiency is a related alternative.','Other congenital features and inheritance patterns vary.'], '**Assess puberty induction and fertility separately.**',['Evaluate associated anomalies and genetics.','Treatment can restore sex steroids and, using appropriate stimulation, support fertility in selected patients.'],[['Hormonal pattern','Hypogonadotropic hypogonadism'],['Smell','Reduced/absent'],['Mechanism','Congenital GnRH deficiency']],[KA],'clinical_scenario')
q('A tall man has small firm testes, infertility, gynecomastia and high LH/FSH with low testosterone. Which test can establish the suspected chromosomal disorder?', 'Karyotype analysis for Klinefelter syndrome',[
 ('A normal smell test alone','This does not establish a sex-chromosome diagnosis.'),('A low-dose dexamethasone test','It assesses a different axis.'),('A single prolactin measurement as definitive confirmation','It cannot identify the chromosomal pattern.')],
 'A primary testicular phenotype can have a chromosomal cause', '**The common karyotype is 47,XXY, with variants and mosaicism.**',['Presentation is variable and can be recognized late.','Bone, metabolic and psychosocial consequences need care.'], '**Discuss testosterone and fertility options with specialists.**',['Do not assume that every patient has identical fertility potential.','Use genetic counseling and appropriate long-term surveillance.'],[['Testes','Often small/firm'],['Hormones','Primary/hypergonadotropic pattern'],['Confirmation','Karyotype']],[KL],'clinical_scenario')
q('A man presents with a hard unilateral breast mass, nipple retraction and no typical soft symmetric subareolar enlargement. What is the priority?', 'Evaluate for malignancy rather than assuming benign gynecomastia',[
 ('All male breast enlargement is harmless adipose tissue','A discrete suspicious lesion needs assessment.'),('Testosterone should be prescribed before examining the lesion','This delays diagnosis and may be inappropriate.'),('A drug history alone safely excludes breast cancer','It does not remove suspicious structural findings.')],
 'True gynecomastia and a suspicious breast lesion require different pathways', '**Examination should distinguish glandular proliferation, adiposity and a discrete mass.**',['Medicines, gonadal disease and systemic causes are relevant in ordinary gynecomastia.','Suspicious signs prompt appropriate imaging and tissue assessment.'], '**Do not reassure from sex or a presumed hormonal explanation.**',['Examine testes and assess hormones when the context indicates.','Coordinate timely breast evaluation.'],[['Benign pattern','Often subareolar glandular tissue'],['Red flags','Hard mass/retraction/skin change'],['Action','Malignancy assessment']],[GY],'clinical_scenario')

if __name__=='__main__':finalize('Endocrine',10,'Reproductive Endocrinology and PCOS','endo-reproductive-pcos',rows,24)
